mapper.select:
SELECT * FROM ( SELECT SEC_INFO.SEC_ID secId, SEC_INFO.BOND_NAME bondName, SEC_INFO.BOND_ABBREVIATION bondAbbreviation, SEC_INFO.TRADING_PLACES tradingPlaces, SEC_INFO.REGISTERED_CUSTODIAN registeredCustodian, SEC_INFO.RAISE_MODE raiseMode,
nvl(RDI_RELEASE_INFO.ISSUE_METHOD ,RELEASE_INFO.ISSUING_METHOD) as issueMethod,
RELEASE_INFO.BIDDING_METHOD as biddingMethod, RELEASE_INFO.TENDER_TARGET as tenderTarget, RELEASE_INFO.ADDITIONAL_BATCHES as additionalBatches,
nvl(RDI_RELEASE_INFO.ISSUE_SIZE * 10000 , ROUND(RELEASE_INFO.ISSUE_SIZE / 10000, 2)) as issueSize,
nvl( to_char(RDI_RELEASE_INFO.ISSUE_DATE,'yyyy-mm-dd hh:mm:ss'), to_char(RELEASE_INFO.ISSUE_DATE,'yyyy-mm-dd hh:mm:ss')) AS issueDate,
nvl( to_char(RDI_RELEASE_INFO.EVENT_DATE,'yyyy-mm-dd hh:mm:ss'), to_char(RELEASE_INFO.PAYMENT_DEADLINE,'yyyy-mm-dd hh:mm:ss')) AS eventDate,
RELEASE_INFO.DEBT_REGISTRATION_DATE as debtRegistrationDate,
RELEASE_INFO.LISTING_DATE as listingDate, RELEASE_INFO.LISTING_CODE as listingCode, SEC_INFO.CROSS_MARKET_CODE as crossMarketCode,
nvl( to_char(RDI_RELEASE_INFO.INTEREST_ACCRUAL_DATE,'yyyy-mm-dd hh:mm:ss'), to_char(RELEASE_INFO.INTEREST_ACCRUAL_DATE,'yyyy-mm-dd hh:mm:ss')) AS interestAccrualDate,
SEC_INFO.VALUE_DATE valueDate, SEC_INFO.EXPIRY_DATE expiryDate, SEC_INFO.PRIMARY_CLASSIFICATION primaryClassification, SEC_INFO.SECONDARY_CLASSIFICATION secondaryClassification, SEC_INFO.VARIETY_OF_COUPONS couponSpecies, SEC_INFO.INTEREST_PAYMENT_FREQUENCY interestPaymentFrequency, SEC_INFO.RATE_TYPE rateType, SEC_INFO.CURRENCY,
nvl(RDI_RELEASE_INFO.ISSUE_PX, RELEASE_INFO.ISSUE_PX) as issuePx, nvl(RDI_RELEASE_INFO.STIPULATION_VALUE, RELEASE_INFO.STIPULATION_VALUE) as stipulationValue,
nvl(RDI_RELEASE_INFO.SINGLE_MIN_SUB_AMT * 10000, ROUND(RELEASE_INFO.SINGLE_MAX_SUB_AMT / 10000, 2)) as singleMinSubAmt, nvl(RDI_RELEASE_INFO.SINGLE_MAX_SUB_AMT * 10000, ROUND(RELEASE_INFO.SINGLE_MAX_SUB_AMT / 10000, 2)) as singleMaxSubAmt, RDI_RELEASE_INFO.REMARK as REMARK, PRODUCT.FINPROD_ID FINPRODID FROM INTERF_WIND_UNRELEASE_SEC_INFO SEC_INFO LEFT JOIN INTERF_WIND_RELEASE_INFO RELEASE_INFO ON SEC_INFO.SEC_ID = RELEASE_INFO.SEC_ID LEFT JOIN INTERF_RDI_RELEASE_INFO RDI_RELEASE_INFO ON RDI_RELEASE_INFO.SECURITY_ID = SEC_INFO.SEC_ID LEFT JOIN FIN_PRODUCT PRODUCT on SEC_INFO.SEC_ID = PRODUCT.FINPROD_MARKET_ID
SEC_INFO.VALUE_DATE < to_date(#{platformDate}, 'yyyy-MM-dd')
AND SEC_INFO.SECID = #{secId,jdbcType=VARCHAR}
AND SEC_INFO.MARKET = #{tradingPlaces,jdbcType=VARCHAR}
AND SEC_INFO.institution = #{registeredCustodian,jdbcType=VARCHAR}
AND SEC_INFO.ISSUERSHORT = #{issuer,jdbcType=VARCHAR}
AND SEC_INFO.PUBENDDATE >= #{issueDateStart,jdbcType=DATE}
AND SEC_INFO.PUBENDDATE <= #{issueDateEnd,jdbcType=DATE}
AND SEC_INFO.VDATE >= #{vdateStart,jdbcType=DATE}
AND SEC_INFO.VDATE <= #{vdateEnd,jdbcType=DATE}
AND SEC_INFO.MDATE >= #{mdateStart,jdbcType=DATE}
AND SEC_INFO.MDATE <= #{mdateEnd,jdbcType=DATE}
AND SEC_INFO.THEORYOPTIONPAYDAY >= #{theOryOptionPayDayStart,jdbcType=DATE}
AND SEC_INFO.THEORYOPTIONPAYDAY <= #{theOryOptionPayDayEnd,jdbcType=DATE}
AND SEC_INFO.COUPONSPECIES = #{couponSpecies,jdbcType=VARCHAR}
AND SEC_INFO.INTERESTRATE = #{rateType,jdbcType=VARCHAR}
AND SEC_INFO.PAYCYCLE = #{interestPaymentFrequency,jdbcType=VARCHAR}
AND SEC_INFO.CURRENCY = #{currency,jdbcType=VARCHAR}
AND SEC_INFO.ISSUS = #{isSus,jdbcType=VARCHAR}
AND ( SEC_INFO.CALLOPTION = 'Y' OR SEC_INFO.PUTOPTION = 'Y')
AND ( SEC_INFO.CALLOPTION = 'N' AND SEC_INFO.PUTOPTION = 'N')
AND SEC_INFO.OPTIONTYPE = #{optionType,jdbcType=VARCHAR}
AND SEC_INFO.RATING in (#{zxGrade,jdbcType=VARCHAR})
AND SEC_INFO.RATING in (#{ztGrade,jdbcType=VARCHAR})
AND ( SEC_INFO.SEC_ID like '%' || #{search} || '%' OR SEC_INFO.MARKET like '%' || #{search} || '%' OR SEC_INFO.ISSUERSHORT like '%' || #{search} || '%' OR to_char(SEC_INFO.PUBENDDATE,'yyyy-MM-dd') = #{search} OR to_char(SEC_INFO.VDATE,'yyyy-MM-dd') = #{search} OR to_char(SEC_INFO.MDATE,'yyyy-MM-dd') = #{search} OR to_char(SEC_INFO.THEORYOPTIONPAYDAY,'yyyy-MM-dd') = #{search} OR SEC_INFO.COUPONSPECIES like '%' || #{search} || '%' OR SEC_INFO.INTERESTRATE like '%' || #{search} || '%' OR SEC_INFO.PAYCYCLE like '%' || #{search} || '%' OR SEC_INFO.CCY like '%' || #{search} || '%' OR SEC_INFO.ISSUS like '%' || #{search} || '%' OR SEC_INFO.OPTIONTYPE like '%' || #{search} || '%' OR SEC_INFO.RATING like '%' || #{search} || '%' OR SEC_INFO.RATING like '%' || #{search} || '%' )
) ORDER BY PRIMARYCLASSIFICATION, SECONDARYCLASSIFICATION, ISSUEDATE, SECID

SELECT
SEQNO,
CONFIG_TYPE configType,
INPUT_VALUE_1 inputValue1,
INPUT_VALUE_1 inputValue2,
INPUT_VALUE_1 inputValue3,
INPUT_VALUE_1 inputValue4,
INPUT_VALUE_1 inputValue5,
OUTPUT_VALUE_1 outputValue1,
OUTPUT_VALUE_2 outputValue2,
OUTPUT_VALUE_3 outputValue3,
OUTPUT_VALUE_4 outputValue4,
OUTPUT_VALUE_5 outputValue5
FROM FIN_PRODUCT_TYPE_CONFIG
WHERE CONFIG_TYPE = #{configType}

    AND INPUT_VALUE_1 = #{inputValue1}


    AND INPUT_VALUE_2 = #{inputValue2}


    AND INPUT_VALUE_3 = #{inputValue3}


    AND OUTPUT_VALUE_1 = #{outputValue1}


    AND OUTPUT_VALUE_2 = #{outputValue2}


    AND OUTPUT_VALUE_3 = #{outputValue3}

and ROWNUM = 1
